Method.Implementation:
 set root = 1
 set xmlString = ""
 $$$TRACE( obj.%ToJSON())


	 set writer=##class(%XML.Writer).%New()
	 set writer.Charset="UTF-8"
	 set sc=writer.OutputToString()
	 If $$$ISERR(sc) Do $system.OBJ.DisplayError(sc) Quit


 	 set iter = obj.%GetIterator()
	 While iter.%GetNext(.key , .value ) 
	 {
	      $$$TRACE( "Key = "_key_" _ Value = "_value)


	      IF ($$$IsdefObject(value) && value.%IsA("%Library.DynamicAbstractObject") )
	      {
	      	$$$TRACE( key _ ": Array")
	      	if (root = 1)
	      	{
		      	$$$TRACE( "Add root, %Library.DynamicAbstractObject: " _ key)
	      		s sc=writer.RootElement(key)
	      		SET key=$ORDER(attrArray(""))
			   	WHILE (key'="") {
				   $$$TRACE( "Add Attribute " _ key _ ", " _ attrArray(key))
			     	Do writer.WriteAttribute(key, attrArray(key))
			     	// Get next subscript 
			     	SET key = $ORDER(attrArray(key))
			    }

	      	}
	      	$$$TRACE( "Call WriteDynamicObject: " _ value _", " _ key)

	      	Do ..WriteDynamicObject(value, key, writer, 0)
	      	set root = 0


	      }
	      else
	      {
		      if ($EXTRACT(key,1) = "@")
		      {
			      $$$TRACE( "Get Attribute " _ key)
			      if (root = 0)
			      {
			        Do writer.WriteAttribute($EXTRACT(key, 2, *), value)
			      }
			      else
			      {
				      // root not added yet
			      	set attrArray($EXTRACT(key, 2, *)) = value
			      }
		      }
		      else
		      {
			      	if (root = 1)
			      	{
				      	$$$TRACE( "Add root")
			      		s sc=writer.RootElement("root")

			      		SET key=$ORDER(attrArray(""))
					   	WHILE (key'="") {
						   $$$TRACE( "Add Attribute " _ key _ ", " _ attrArray(key))
					     	Do writer.WriteAttribute(key, attrArray(key))
					     	// Get next subscript 
					     	SET key = $ORDER(attrArray(key))
					    }
			      	}
				    $$$TRACE( "Add Element: " _ key _ ": " _ value)
			      	Do writer.Element(key)
			      	Do writer.WriteChars(value)
			      	set status=writer.EndElement()


			      	set root = 0
		      }
	      }


	   } 



	 s sc=writer.EndRootElement()
	 If $$$ISERR(sc) Do $system.OBJ.DisplayError(sc) Quit
	 s xmlString=writer.GetXMLString()
	 $$$TRACE( "OUTPUT: " _ xmlString)
	 return xmlString

set addEnd = 0
$$$TRACE( "WriteDynamicObject: Arr: " _ arr)
if ($$$IsdefObject(obj) && obj.%IsA("%Library.DynamicArray"))
{
	$$$TRACE( "DynamicArray : " _ prevKey _ " Tag: " _ obj.%ToJSON())
	set arr = 1

}
elseIF ($$$IsdefObject(obj) && obj.%IsA("%Library.DynamicObject") )
{
	if (prevKey '= "")
	{
		$$$TRACE( "Add DynamicObject : " _ prevKey _ " Tag: " _ obj.%ToJSON())
		Do writer.Element(prevKey)
		set addEnd = 1
	}
}
elseif (prevKey '= "")
{
	$$$TRACE( "Add Element : " _ prevKey )
 	Do writer.Element(prevKey)
 	set addEnd = 1
}



IF ($$$IsdefObject(obj) && obj.%IsA("%Library.DynamicAbstractObject") )
{
	set iter = obj.%GetIterator()
	while iter.%GetNext(.key , .value ) {
		$$$TRACE( "WriteDynamicObject Call WriteDynamicObject " _ prevKey _ "."_key_" : value = "_value)
		if arr = 1
		{
			// Array index, send the arry name
			Do ..WriteDynamicObject(value, prevKey, writer, arr)
		}
		else
		{
			Do ..WriteDynamicObject(value, key, writer, arr)
		}
	}	      			
}
else
{
	Do writer.WriteChars(obj)
}
if (addEnd = 1)
{
	Do writer.EndElement()
}
set arr = 0
